int mod=998244353;
void add(int &x,int y)
{
	x+=y;
	if(x>=mod) x-=mod;
}
int n,m,i,j,msk,cpx,cnx,cpy,cny,bx,by,dp[31][21][21][21][21][2][2],x[15],y[15],px[1<<5],py[1<<5],nx[1<<5],ny[1<<5];
int main()
{
	read(n);read(m);
	rep(i,n){
		read(x[i]);
		read(y[i]);
	}
	forup(i,0,(1<<n)-1){
		rep(j,n){
			if((i>>(j-1))&1){
				(x[j]>0?px[i]:nx[i])+=abs(x[j]);
				(y[j]>0?py[i]:ny[i])+=abs(y[j]);
			}
		}
	}
	dp[0][0][0][0][0][0][0]=1;
	forup(i,0,29){
		forup(cpx,0,19)forup(cnx,0,19)forup(cpy,0,19)forup(cny,0,19){
			forup(bx,0,1)forup(by,0,1)if(dp[i][cpx][cnx][cpy][cny][bx][by]){
				forup(msk,0,(1<<n)-1){
					int npx=cpx+px[msk];
					int npy=cpy+py[msk];
					int nnx=cnx+nx[msk];
					int nny=cny+ny[msk];
					if((npx&1)!=(nnx&1)) continue;
					if((npy&1)!=(nny&1)) continue;
					int cx=(npx&1),cy=(npy&1);
					int mx=((m>>i)&1),my=mx;
					add(dp[i+1][npx>>1][nnx>>1][npy>>1][nny>>1][(cx==mx)?bx:(cx>mx)][(cy==my)?by:(cy>my)],dp[i][cpx][cnx][cpy][cny][bx][by]);
				}
			}
		}
	}
	cout<<(dp[30][0][0][0][0][0][0]+mod-1)%mod;
	return 0;
}
